import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse(`{"title":"Rules Engine","description":"Intercept and transform HTTP traffic with NectoProxy's powerful rules engine.","frontmatter":{"title":"Rules Engine","description":"Intercept and transform HTTP traffic with NectoProxy's powerful rules engine."},"headers":[],"relativePath":"features/rules-engine.md","filePath":"features/rules-engine.md","lastUpdated":1772297611000}`),i={name:"features/rules-engine.md"};function o(r,e,l,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="rules-engine" tabindex="-1">Rules Engine <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;Rules Engine&quot;">​</a></h1><p>The Rules Engine is NectoProxy&#39;s system for automatically intercepting and transforming HTTP traffic based on conditions you define. Rules let you mock responses, block requests, modify headers, simulate latency, and much more -- all without changing a single line of application code.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A rule consists of two parts:</p><ol><li><strong>Matching conditions</strong> -- Determine which requests the rule applies to</li><li><strong>Action</strong> -- What happens when a matching request is intercepted</li></ol><p>When a request passes through NectoProxy, it is evaluated against all enabled rules in priority order. The first matching rule&#39;s action is applied. If no rules match, the request proceeds normally to the target server.</p><h2 id="rule-actions" tabindex="-1">Rule Actions <a class="header-anchor" href="#rule-actions" aria-label="Permalink to &quot;Rule Actions&quot;">​</a></h2><p>NectoProxy supports 8 distinct rule actions. Each action is designed for a specific debugging or testing scenario.</p><h3 id="mock-response" tabindex="-1">Mock Response <a class="header-anchor" href="#mock-response" aria-label="Permalink to &quot;Mock Response&quot;">​</a></h3><p>Return a custom response without forwarding the request to the server. You define the status code, headers, and body.</p><p><strong>Use cases:</strong></p><ul><li>Test UI behavior against specific API responses before the backend is ready</li><li>Simulate error responses (500, 503, 429) to verify error handling</li><li>Provide deterministic responses for automated testing</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Mock responses are served directly by NectoProxy, so they are extremely fast -- typically under 1ms. This makes them ideal for development workflows where you need to iterate quickly on UI code.</p></div><h3 id="block-request" tabindex="-1">Block Request <a class="header-anchor" href="#block-request" aria-label="Permalink to &quot;Block Request&quot;">​</a></h3><p>Reject the request entirely. The client receives a connection reset or a configurable error response.</p><p><strong>Use cases:</strong></p><ul><li>Block analytics and tracking scripts during development</li><li>Prevent specific API calls from reaching the server</li><li>Simulate network-level failures</li></ul><h3 id="modify-request" tabindex="-1">Modify Request <a class="header-anchor" href="#modify-request" aria-label="Permalink to &quot;Modify Request&quot;">​</a></h3><p>Alter the outgoing request before it reaches the server. You can modify headers, query parameters, or the request body.</p><p><strong>Use cases:</strong></p><ul><li>Inject authentication headers for testing</li><li>Modify API request payloads to test edge cases</li><li>Override <code>User-Agent</code> or <code>Accept-Language</code> headers</li></ul><h3 id="modify-response" tabindex="-1">Modify Response <a class="header-anchor" href="#modify-response" aria-label="Permalink to &quot;Modify Response&quot;">​</a></h3><p>Alter the response received from the server before it reaches the client. You can modify response headers, status codes, or the body.</p><p><strong>Use cases:</strong></p><ul><li>Inject CORS headers to bypass cross-origin restrictions during development</li><li>Modify API response payloads to test UI edge cases</li><li>Override caching headers</li></ul><h3 id="map-local" tabindex="-1">Map Local <a class="header-anchor" href="#map-local" aria-label="Permalink to &quot;Map Local&quot;">​</a></h3><p>Serve a response from a local file instead of forwarding the request to the server. Point the rule to a file on your filesystem, and its contents are returned as the response body.</p><p><strong>Use cases:</strong></p><ul><li>Replace a remote JavaScript bundle with a local development build</li><li>Serve modified CSS for quick visual debugging</li><li>Return a local JSON file as an API response</li></ul><h3 id="map-remote" tabindex="-1">Map Remote <a class="header-anchor" href="#map-remote" aria-label="Permalink to &quot;Map Remote&quot;">​</a></h3><p>Redirect the request to a different URL. The request is forwarded to the mapped URL instead of the original destination.</p><p><strong>Use cases:</strong></p><ul><li>Redirect API calls from production to a staging server</li><li>Test against a different backend version without changing client configuration</li><li>Route specific paths to a local development server</li></ul><h3 id="delay" tabindex="-1">Delay <a class="header-anchor" href="#delay" aria-label="Permalink to &quot;Delay&quot;">​</a></h3><p>Add a fixed delay (in milliseconds) before forwarding the request. The request is held for the specified duration and then sent to the server normally.</p><p><strong>Use cases:</strong></p><ul><li>Test loading states and skeleton screens in the UI</li><li>Verify timeout handling in client code</li><li>Simulate slow API responses for performance testing</li></ul><h3 id="throttle" tabindex="-1">Throttle <a class="header-anchor" href="#throttle" aria-label="Permalink to &quot;Throttle&quot;">​</a></h3><p>Limit the bandwidth for matching requests. You specify a maximum throughput in kilobytes per second.</p><p><strong>Use cases:</strong></p><ul><li>Simulate slow file downloads</li><li>Test progressive image loading behavior</li><li>Verify chunked response handling in the client</li></ul><hr><h2 id="matching-conditions" tabindex="-1">Matching Conditions <a class="header-anchor" href="#matching-conditions" aria-label="Permalink to &quot;Matching Conditions&quot;">​</a></h2><p>Rules are triggered based on matching conditions. You can combine multiple conditions for precise targeting.</p><h3 id="url-pattern-matching" tabindex="-1">URL Pattern Matching <a class="header-anchor" href="#url-pattern-matching" aria-label="Permalink to &quot;URL Pattern Matching&quot;">​</a></h3><p>URL patterns determine which requests a rule applies to. NectoProxy supports three pattern syntaxes:</p><h4 id="glob-patterns" tabindex="-1">Glob Patterns <a class="header-anchor" href="#glob-patterns" aria-label="Permalink to &quot;Glob Patterns&quot;">​</a></h4><p>Use <code>*</code> to match any sequence of characters within a path segment, and <code>**</code> to match across path segments.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.example.com/v1/users/*</span></span>
<span class="line"><span>https://cdn.example.com/assets/**/*.js</span></span>
<span class="line"><span>*://example.com/api/*</span></span></code></pre></div><h4 id="wildcard-patterns" tabindex="-1">Wildcard Patterns <a class="header-anchor" href="#wildcard-patterns" aria-label="Permalink to &quot;Wildcard Patterns&quot;">​</a></h4><p>A simplified syntax where <code>*</code> matches any sequence of characters.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*example.com*</span></span>
<span class="line"><span>*api/v2*</span></span>
<span class="line"><span>*.js</span></span></code></pre></div><h4 id="regular-expressions" tabindex="-1">Regular Expressions <a class="header-anchor" href="#regular-expressions" aria-label="Permalink to &quot;Regular Expressions&quot;">​</a></h4><p>For advanced matching, use full regular expressions. Prefix the pattern with <code>regex:</code> to enable regex mode.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regex:https?://api\\\\.example\\\\.com/v[12]/users/\\\\d+</span></span>
<span class="line"><span>regex:.*\\\\.(jpg|png|gif|webp)$</span></span>
<span class="line"><span>regex:https://.*\\\\.example\\\\.com/api/.*</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Regular expressions are powerful but can impact performance if overly complex. Use simpler glob or wildcard patterns when they are sufficient for your needs.</p></div><h3 id="method-matching" tabindex="-1">Method Matching <a class="header-anchor" href="#method-matching" aria-label="Permalink to &quot;Method Matching&quot;">​</a></h3><p>Restrict a rule to specific HTTP methods. You can select one or more methods:</p><ul><li><code>GET</code></li><li><code>POST</code></li><li><code>PUT</code></li><li><code>DELETE</code></li><li><code>PATCH</code></li><li><code>HEAD</code></li><li><code>OPTIONS</code></li></ul><p>If no method is specified, the rule matches all methods.</p><h3 id="header-matching" tabindex="-1">Header Matching <a class="header-anchor" href="#header-matching" aria-label="Permalink to &quot;Header Matching&quot;">​</a></h3><p>Match requests based on the presence or value of specific headers. Examples:</p><table tabindex="0"><thead><tr><th>Header</th><th>Operator</th><th>Value</th><th>Matches</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>equals</td><td><code>application/json</code></td><td>Only JSON requests</td></tr><tr><td><code>Authorization</code></td><td>exists</td><td>--</td><td>Any request with an auth header</td></tr><tr><td><code>X-Custom-Header</code></td><td>contains</td><td><code>debug</code></td><td>Requests with debug in custom header</td></tr></tbody></table><h3 id="body-content-matching" tabindex="-1">Body Content Matching <a class="header-anchor" href="#body-content-matching" aria-label="Permalink to &quot;Body Content Matching&quot;">​</a></h3><p>Match requests based on their body content. This is useful for targeting specific API calls that share the same URL but differ in payload.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;createUser&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Body matching supports partial string matching -- the rule triggers if the request body contains the specified string.</p><hr><h2 id="rule-priority" tabindex="-1">Rule Priority <a class="header-anchor" href="#rule-priority" aria-label="Permalink to &quot;Rule Priority&quot;">​</a></h2><p>When multiple rules could match a request, NectoProxy uses the <strong>priority</strong> value to determine which rule takes effect. The rule with the <strong>lowest priority number</strong> wins.</p><table tabindex="0"><thead><tr><th>Priority</th><th>Rule Name</th><th>Action</th></tr></thead><tbody><tr><td>1</td><td>Block Analytics</td><td>Block</td></tr><tr><td>2</td><td>Mock User API</td><td>Mock</td></tr><tr><td>3</td><td>Add CORS Headers</td><td>Modify Response</td></tr><tr><td>10</td><td>Slow API</td><td>Delay</td></tr></tbody></table><p>In this example, if a request matches both &quot;Block Analytics&quot; and &quot;Mock User API,&quot; the Block rule is applied because it has a lower priority number (1 &lt; 2).</p><div class="tip custom-block"><p class="custom-block-title">Managing Priorities</p><p>You can reorder rules using <strong>drag-and-drop</strong> in the Web UI. Dragging a rule above or below other rules automatically updates the priority values. This is the easiest way to adjust rule evaluation order.</p></div><h2 id="enabling-and-disabling-rules" tabindex="-1">Enabling and Disabling Rules <a class="header-anchor" href="#enabling-and-disabling-rules" aria-label="Permalink to &quot;Enabling and Disabling Rules&quot;">​</a></h2><p>Each rule has an <strong>enable/disable toggle</strong> in the UI. Disabled rules are not evaluated during request processing, but their configuration is preserved. This lets you keep rules configured for occasional use without them affecting normal traffic.</p><details class="details custom-block"><summary>Bulk Operations</summary><p>You can enable or disable multiple rules at once by selecting them in the rules list and using the bulk action buttons. This is useful when switching between different testing scenarios that require different rule sets.</p></details><h2 id="organizing-rules" tabindex="-1">Organizing Rules <a class="header-anchor" href="#organizing-rules" aria-label="Permalink to &quot;Organizing Rules&quot;">​</a></h2><h3 id="drag-and-drop-reordering" tabindex="-1">Drag-and-Drop Reordering <a class="header-anchor" href="#drag-and-drop-reordering" aria-label="Permalink to &quot;Drag-and-Drop Reordering&quot;">​</a></h3><p>The rules list supports drag-and-drop reordering. Grab a rule by its handle and drag it to a new position. The priority values are automatically recalculated based on the new order. This visual approach to priority management is more intuitive than manually editing priority numbers.</p><hr><h2 id="rule-configuration-examples" tabindex="-1">Rule Configuration Examples <a class="header-anchor" href="#rule-configuration-examples" aria-label="Permalink to &quot;Rule Configuration Examples&quot;">​</a></h2><h3 id="example-1-mock-a-rest-api-endpoint" tabindex="-1">Example 1: Mock a REST API Endpoint <a class="header-anchor" href="#example-1-mock-a-rest-api-endpoint" aria-label="Permalink to &quot;Example 1: Mock a REST API Endpoint&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL Pattern:   https://api.example.com/v1/users/123</span></span>
<span class="line"><span>Method:        GET</span></span>
<span class="line"><span>Action:        Mock Response</span></span>
<span class="line"><span>Status Code:   200</span></span>
<span class="line"><span>Headers:       Content-Type: application/json</span></span>
<span class="line"><span>Body:</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;id&quot;: 123,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;Jane Doe&quot;,</span></span>
<span class="line"><span>  &quot;email&quot;: &quot;jane@example.com&quot;,</span></span>
<span class="line"><span>  &quot;role&quot;: &quot;admin&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="example-2-block-third-party-scripts" tabindex="-1">Example 2: Block Third-Party Scripts <a class="header-anchor" href="#example-2-block-third-party-scripts" aria-label="Permalink to &quot;Example 2: Block Third-Party Scripts&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL Pattern:   *://analytics.tracking.com/**</span></span>
<span class="line"><span>Method:        (any)</span></span>
<span class="line"><span>Action:        Block</span></span></code></pre></div><h3 id="example-3-add-cors-headers-to-api-responses" tabindex="-1">Example 3: Add CORS Headers to API Responses <a class="header-anchor" href="#example-3-add-cors-headers-to-api-responses" aria-label="Permalink to &quot;Example 3: Add CORS Headers to API Responses&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL Pattern:   https://api.example.com/**</span></span>
<span class="line"><span>Method:        (any)</span></span>
<span class="line"><span>Action:        Modify Response</span></span>
<span class="line"><span>Add Headers:</span></span>
<span class="line"><span>  Access-Control-Allow-Origin: http://localhost:3000</span></span>
<span class="line"><span>  Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS</span></span>
<span class="line"><span>  Access-Control-Allow-Headers: Content-Type, Authorization</span></span></code></pre></div><h3 id="example-4-simulate-slow-api" tabindex="-1">Example 4: Simulate Slow API <a class="header-anchor" href="#example-4-simulate-slow-api" aria-label="Permalink to &quot;Example 4: Simulate Slow API&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL Pattern:   https://api.example.com/v1/search*</span></span>
<span class="line"><span>Method:        (any)</span></span>
<span class="line"><span>Action:        Delay</span></span>
<span class="line"><span>Delay:         3000ms</span></span></code></pre></div><hr><h2 id="detailed-rule-documentation" tabindex="-1">Detailed Rule Documentation <a class="header-anchor" href="#detailed-rule-documentation" aria-label="Permalink to &quot;Detailed Rule Documentation&quot;">​</a></h2><p>For in-depth documentation on each rule action type, see the individual rule pages:</p><ul><li><a href="/rules/mock.html">Mock Response</a></li><li><a href="/rules/block.html">Block Request</a></li><li><a href="/rules/modify-request.html">Modify Request</a></li><li><a href="/rules/modify-response.html">Modify Response</a></li><li><a href="/rules/map-local.html">Map Local</a></li><li><a href="/rules/map-remote.html">Map Remote</a></li><li><a href="/rules/delay.html">Delay</a></li><li><a href="/rules/throttle.html">Throttle</a></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Rules are persisted across NectoProxy sessions. Any rules you create are saved and automatically loaded the next time you start the proxy.</p></div>`,94)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
